// Content hashing for the persistent face cache: text hashes key
// cached faces by their source and generated bytes; the tree hash is a
// build's identity — a change ANYWHERE in a hashed tree (nested
// runtime/ fragments and grammar output included) must purge what that
// build produced.
//
// Separate from the server so the hashing is unit-testable without
// spawning a live LSP session.

import fs from 'node:fs';
import path from 'node:path';

export const hashText = (text) => Bun.hash(text).toString(16);

// Recursive content hash over a directory tree's .js modules, keyed by
// tree-relative path so renames change the hash too. Directories named
// `test` and dot-directories are outside the build's identity;
// parser.js is generated, so grammar changes surface through it.
export function hashTree(dir) {
  const parts = [];
  const walk = (d, rel) => {
    let entries;
    try { entries = fs.readdirSync(d, { withFileTypes: true }); } catch { return; }
    entries.sort((a, b) => (a.name < b.name ? -1 : 1));
    for (const entry of entries) {
      if (entry.name.startsWith('.') || entry.name === 'node_modules' || entry.name === 'test') continue;
      if (entry.isDirectory()) {
        walk(path.join(d, entry.name), rel + entry.name + '/');
      } else if (entry.name.endsWith('.js')) {
        parts.push(rel + entry.name + ':' + Bun.hash(fs.readFileSync(path.join(d, entry.name))).toString(16));
      }
    }
  };
  walk(dir, '');
  return Bun.hash(parts.join(';')).toString(16);
}

// The manifest's identity, over BOTH trees whose code it caches the
// products of: the compiler that built each face, and the SERVER that
// derived each file's closure edge list (ripImportsOf). Keying on the
// compiler alone leaves the second half unversioned — change which
// spellings count as an edge and every warm workspace goes on serving
// lists the old rule produced, invisibly, until each file is next
// edited. Order matters, so the two trees can never trade places.
export const cacheIdentityOf = (compilerDir, serverDir) =>
  hashText(`compiler:${hashTree(compilerDir)};server:${hashTree(serverDir)}`);
